import os


class AzureSpeechClient:
    def __init__(self, api_key=None, region=None):
        self.api_key = api_key or os.environ.get('AZURE_SPEECH_KEY')
        self.region = region or os.environ.get('AZURE_SPEECH_REGION', 'eastus')
        if not self.api_key:
            raise ValueError("Azure Speech API key not provided and AZURE_SPEECH_KEY environment variable not set.")
        if not self.region:
            raise ValueError("Azure Speech region not provided and AZURE_SPEECH_REGION environment variable not set.")

    def get_headers(self):
        return {
            'Ocp-Apim-Subscription-Key': self.api_key,
            'Content-Type': 'application/json'
        }

    def get_base_url(self):
        return f"https://{self.region}.api.cognitive.microsoft.com/speechtotext/v3.1"

class TranscriptionRequest:
    def __init__(self, audio_uri, language_code, display_name="transcription", diarization_enabled=False, word_level_timestamps_enabled=True):
        self.audio_uri = audio_uri
        self.language_code = language_code
        self.display_name = display_name
        self.diarization_enabled = diarization_enabled
        self.word_level_timestamps_enabled = word_level_timestamps_enabled

    def to_json(self):
        return {
            'displayName': self.display_name,
            'locale': self.language_code,
            'contentUrls': [self.audio_uri],
            'properties': {
                'diarizationEnabled': self.diarization_enabled,
                'wordLevelTimestampsEnabled': self.word_level_timestamps_enabled
            }
        }


class TranscriptionResult:
    def __init__(self, raw_result):
        self.raw_result = raw_result
        self.status = raw_result.get('status')
        self.job_id = raw_result.get('self')
        self.display_name = raw_result.get('displayName')
        self.locale = raw_result.get('locale')

    def get_transcript_text(self):
        # This is a simplified example. Actual parsing would be more complex
        # depending on the structure of the Azure Speech-to-Text output JSON.
        # Assuming a structure where 'combinedRecognizedPhrases' is available
        # in the content URL result for a simple text representation.
        # For word-level timestamps and diarization, a more detailed parse would be needed.
        if self.raw_result and 'combinedRecognizedPhrases' in self.raw_result:
            return " ".join([phrase['display'] for phrase in self.raw_result['combinedRecognizedPhrases']])
        return None

    def get_word_timestamps(self):
        # Placeholder for extracting word-level timestamps
        # This would require detailed parsing of the 'segments' or 'recognizedPhrases'
        # arrays from the content URL result if word-level timestamps were enabled.
        if self.raw_result and 'recognizedPhrases' in self.raw_result:
            timestamps = []
            for phrase in self.raw_result['recognizedPhrases']:
                for word in phrase.get('words', []):
                    timestamps.append({
                        'word': word['word'],
                        'offset': word['offset'],
                        'duration': word['duration']
                    })
            return timestamps
        return None

    def get_diarization_speakers(self):
        # Placeholder for extracting speaker diarization information
        # This would involve iterating through segments and their speaker IDs.
        if self.raw_result and 'recognizedPhrases' in self.raw_result:
            speakers = {}
            for phrase in self.raw_result['recognizedPhrases']:
                if 'speaker' in phrase:
                    speaker_id = phrase['speaker']
                    if speaker_id not in speakers:
                        speakers[speaker_id] = []
                    speakers[speaker_id].append(phrase['display'])
            return speakers
        return None

import os
from google.cloud import translate_v3 as translate


def translate_transcript(text_segments, target_language_code, config=None):
    config = config or {}
    client = translate.TranslationServiceClient()

    project_id = config.get('project_id') or os.environ.get('GOOGLE_CLOUD_PROJECT')
    if not project_id:
        raise ValueError("Google Cloud Project ID not provided and GOOGLE_CLOUD_PROJECT environment variable not set.")

    parent = f"projects/{project_id}/locations/global"

    translated_segments = []
    for segment in text_segments:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [segment],
                "target_language_code": target_language_code,
            }
        )
        for translation in response.translations:
            translated_segments.append(translation.translated_text)
    return {"translated_segments": translated_segments, "provider": "Google Cloud Translation"}

import os
from google.cloud import language_v1


def moderate_transcript(text_content, config=None):
    config = config or {}
    client = language_v1.LanguageServiceClient()

    document = language_v1.Document(content=text_content, type_=language_v1.Document.Type.PLAIN_TEXT)

    # Available categories: https://cloud.google.com/natural-language/docs/categories
    response = client.classify_text(request={'document': document})

    moderation_results = []
    for category in response.categories:
        moderation_results.append({
            "name": category.name,
            "confidence": category.confidence
        })
    return {"moderation_results": moderation_results, "provider": "Google Cloud Natural Language API"}

import os
import google.generativeai as genai


def archive_summary(transcript_text, config=None):
    config = config or {}
    genai.configure(api_key=config.get('api_key') or os.environ.get('GEMINI_API_KEY'))

    model = genai.GenerativeModel('gemini-pro')

    prompt = f"Summarize the following transcript:

{transcript_text}

Summary:"
    response = model.generate_content(prompt)

    return {"summary": response.text, "provider": "Google Cloud Generative AI (gemini-pro)"}

import os
import google.generativeai as genai


def transcript_embedding(text_segments, config=None):
    config = config or {}
    genai.configure(api_key=config.get('api_key') or os.environ.get('GEMINI_API_KEY'))

    model = genai.GenerativeModel('embedding-001')

    embeddings = []
    for segment in text_segments:
        response = model.embed_content(content=segment)
        embeddings.append(response['embedding'])

    return {"embeddings": embeddings, "provider": "Google Cloud Generative AI (embedding-001)"}
